import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:practise_platform_channel_flutter/battery_screen.dart';
import 'package:practise_platform_channel_flutter/pigeon/battery_api.g.dart';

// Channel names generated by Pigeon (see lib/pigeon/battery_api.g.dart).
// Pattern: dev.flutter.pigeon.<dartPackageName>.<ApiClass>.<method>
const _pigeonPrefix = 'dev.flutter.pigeon.practise_platform_channel_flutter';

// HostApi uses one BasicMessageChannel per method, with Pigeon's codec
const hostChannel = BasicMessageChannel<Object?>(
  '$_pigeonPrefix.BatteryHostApi.getBatteryLevel',
  BatteryHostApi.pigeonChannelCodec,
);

// EventChannelApi uses a normal EventChannel, with Pigeon's codec
const eventChannel = EventChannel(
  '$_pigeonPrefix.BatteryEventApi.batteryUpdates',
  pigeonMethodCodec,
);

// No Kotlin runs in widget tests, so we pretend to be the native side
TestDefaultBinaryMessenger get messenger =>
    TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger;

// Fake Kotlin BatteryStreamHandler: runs onListen when Dart starts listening
void mockBatteryStream(
  void Function(MockStreamHandlerEventSink events) onListen, {
  void Function()? onCancel,
}) {
  messenger.setMockStreamHandler(
    eventChannel,
    MockStreamHandler.inline(
      onListen: (arguments, events) => onListen(events),
      onCancel: (arguments) => onCancel?.call(),
    ),
  );
}

// Fake Kotlin BatteryHostApiImpl.
// Pigeon reply format: [value] on success, [code, message, details] on error.
void mockGetBatteryLevel(List<Object?> Function() reply) {
  messenger.setMockDecodedMessageHandler<Object?>(
    hostChannel,
    (message) async => reply(),
  );
}

Future<void> pumpBatteryScreen(WidgetTester tester) async {
  await tester.pumpWidget(const MaterialApp(home: BatteryScreen()));
  // Let the mocked channel deliver its first event
  await tester.pump();
}

void main() {
  tearDown(() {
    messenger.setMockStreamHandler(eventChannel, null);
    messenger.setMockDecodedMessageHandler<Object?>(hostChannel, null);
  });

  group('EventChannelApi (live stream)', () {
    testWidgets('shows loading until the first event arrives', (tester) async {
      mockBatteryStream((events) {}); // Never sends anything

      await pumpBatteryScreen(tester);

      expect(find.byType(CircularProgressIndicator), findsOneWidget);
    });

    testWidgets('shows level and charging state', (tester) async {
      // Send a typed BatteryInfo, just like Kotlin's sink.success(BatteryInfo(...))
      mockBatteryStream(
        (events) => events.success(BatteryInfo(level: 80, isCharging: true)),
      );

      await pumpBatteryScreen(tester);

      expect(find.text('Battery level: 80%'), findsOneWidget);
      expect(find.text('⚡ Charging'), findsOneWidget);
    });

    testWidgets('shows not charging', (tester) async {
      mockBatteryStream(
        (events) => events.success(BatteryInfo(level: 15, isCharging: false)),
      );

      await pumpBatteryScreen(tester);

      expect(find.text('Battery level: 15%'), findsOneWidget);
      expect(find.text('🔋 Not charging'), findsOneWidget);
    });

    testWidgets('shows native error sent with sink.error()', (tester) async {
      mockBatteryStream(
        (events) => events.error(
          code: 'UNAVAILABLE',
          message: 'Battery info not available.',
        ),
      );

      await pumpBatteryScreen(tester);

      expect(find.text('Battery info not available.'), findsOneWidget);
    });

    testWidgets('cancels the native stream when screen is disposed', (
      tester,
    ) async {
      var cancelled = false;
      mockBatteryStream(
        (events) => events.success(BatteryInfo(level: 80, isCharging: true)),
        onCancel: () => cancelled = true,
      );

      await pumpBatteryScreen(tester);
      expect(cancelled, isFalse);

      // Remove the screen from the tree, which calls dispose()
      await tester.pumpWidget(const SizedBox());

      expect(cancelled, isTrue);
    });
  });

  group('HostApi (refresh once)', () {
    testWidgets('shows one-time level with unknown charging state', (
      tester,
    ) async {
      mockBatteryStream(
        (events) => events.success(BatteryInfo(level: 80, isCharging: true)),
      );
      var calls = 0;
      mockGetBatteryLevel(() {
        calls++;
        return [42];
      });

      await pumpBatteryScreen(tester);
      await tester.tap(find.text('Refresh once (MethodChannel)'));
      await tester.pump();

      expect(calls, 1);
      expect(find.text('Battery level: 42%'), findsOneWidget);
      expect(
        find.text('Charging status unknown (one-time read)'),
        findsOneWidget,
      );
    });

    testWidgets('shows native error thrown as FlutterError', (tester) async {
      mockBatteryStream(
        (events) => events.success(BatteryInfo(level: 80, isCharging: true)),
      );
      // Same as Kotlin: throw FlutterError("UNAVAILABLE", "...", null)
      mockGetBatteryLevel(
        () => ['UNAVAILABLE', 'Battery level not available.', null],
      );

      await pumpBatteryScreen(tester);
      await tester.tap(find.text('Refresh once (MethodChannel)'));
      await tester.pump();

      expect(find.text('Battery level not available.'), findsOneWidget);
    });
  });
}
